It first scales the weight matrix by its average absolute value, and then round each value to the nearest integer among \{-1, 0, +1\}:

\begin{equation}
    \widetilde{W} = \mathrm{RoundClip}(\frac{W}{\gamma + \epsilon}, -1, 1),
\end{equation}

\begin{equation}
    \mathrm{RoundClip}(x, a, b) = \max(a, \min(b, \mathrm{round}(x))),
\end{equation}

\begin{equation}
    \gamma = \frac{1}{nm}\sum_{ij} |W_{ij}|.
\end{equation}

Assuming that $k\geq 2$ is a power of $2$, we start by defining the \emph{butterfly factor} $\bm{B}^F(k)$ as

\begin{equation}\label{eq:but_factor}
\footnotesize
\begin{aligned}
    \bm{B}^F(k)=\begin{bmatrix}
    \text{diag}(\bm{d}_1) & \text{diag}(\bm{d}_2) \\
    \text{diag}(\bm{d}_3) & \text{diag}(\bm{d}_4)
    \end{bmatrix}\in\mathbb{R}^{k\times k},
\end{aligned}
\end{equation}

where $\bm{d}_i\in\mathbb{R}^{\frac{k}{2}},\forall i$ are some vectors.

Assuming that $k\geq 2$ is a power of $2$, we start by defining the \emph{butterfly factor} $\bm{B}^F(k)$ as

\begin{equation}\label{eq:but_factor}
\footnotesize
\begin{aligned}
    \bm{B}^F(k)=\begin{bmatrix}
    \text{diag}(\bm{d}_1) & \text{diag}(\bm{d}_2) \\
    \text{diag}(\bm{d}_3) & \text{diag}(\bm{d}_4)
    \end{bmatrix}\in\mathbb{R}^{k\times k},
\end{aligned}
\end{equation}

where $\bm{d}_i\in\mathbb{R}^{\frac{k}{2}},\forall i$ are some vectors.

Combining pieces, the forward pass in BOFT is

\begin{equation}
    \footnotesize
    \begin{aligned}\nonumber
    \bm{z}=\big(\bm{R}(m,b)\cdot\bm{W}^0\big)^\top\bm{x},~~~~\text{s.t.}~\bigg{\{}\bm{R}(m,b)=\prod_{i=1}^m \tilde{\bm{B}}^b_{(d,i)}~~\&~~\underbrace{\big(\tilde{\bm{B}}^b_{(d,j)}\big)^\top\tilde{\bm{B}}^b_{(d,j)}=\tilde{\bm{B}}^b_{(d,j)}\big(\tilde{\bm{B}}^b_{(d,j)}\big)^\top\!=\bm{I}_d}_{\forall j\in [1, m]}\bigg{\}},
    \end{aligned}
\end{equation}

where we denote $\tilde{\bm{B}}^b(d,2^{m - i+1})$ as $\tilde{\bm{B}}^b_{(d,i)}$ for simplicity, and $\bm{I}_d$ is an identity matrix of size $d$.

Combining pieces, the forward pass in BOFT is

\begin{equation}
    \footnotesize
    \begin{aligned}\nonumber
    \bm{z}=\big(\bm{R}(m,b)\cdot\bm{W}^0\big)^\top\bm{x},~~~~\text{s.t.}~\bigg{\{}\bm{R}(m,b)=\prod_{i=1}^m \tilde{\bm{B}}^b_{(d,i)}~~\&~~\underbrace{\big(\tilde{\bm{B}}^b_{(d,j)}\big)^\top\tilde{\bm{B}}^b_{(d,j)}=\tilde{\bm{B}}^b_{(d,j)}\big(\tilde{\bm{B}}^b_{(d,j)}\big)^\top\!=\bm{I}_d}_{\forall j\in [1, m]}\bigg{\}},
    \end{aligned}
\end{equation}

where we denote $\tilde{\bm{B}}^b(d,2^{m - i+1})$ as $\tilde{\bm{B}}^b_{(d,i)}$ for simplicity, and $\bm{I}_d$ is an identity matrix of size $d$.

We calculate the augmented embedding

\begin{align}
e_i &= x_i + \sum_{n = 3,...,8}E_{n}^{hash}(\text{Hash}(g_{i,n})) \\
\text{where, Hash}(g_{i,n}) &= \text{RollPolyHash}(g_{i,n}) \% |E_{n}^{hash}|
\end{align}

Specifically:

\begin{align}
    \text{BPB}(x)&= \frac{\mathcal{L}_{CE}(\pmb{x})}{\ln(2)\cdot n_{\text{bytes}}}
\end{align}

where the uncertainty over the data $\pmb{x}$ as measured by the sum of the cross-entropy loss is normalized by the total number of bytes in $\pmb{x}$ and a constant.

The BT model stipulates that the human preference distribution $p^*$ can be written as:

\begin{equation}\label{eq:bradley-terry}
    p^*(y_1\succ y_2 \mid x)=\frac{\exp\left(r^*(x, y_1)\right)}{\exp\left(r^*(x, y_1)\right) + \exp\left(r^*(x, y_2)\right)}.
\end{equation}

Following prior works~\citep{jaques2017sequence, jaques2020human}, the optimization is formulated as

\begin{equation}\label{eq:RL}
\max_{\pi_{\theta}}  \mathbb{E}_{x\sim \mathcal{D}, y\sim \pi_{\theta}(y \mid x)}\bigl[r_{\phi}(x, y)\bigr] - \beta\mathbb{D}_{\textrm{KL}}\bigl[\pi_{\theta}(y\mid x)\mid \mid \pi_\text{ref}(y\mid x)\bigr],
\end{equation}

We define the projection $f$ as  
\begin{equation}
    f(r; \pi_\text{ref}, \beta)(x, y) = r(x, y) - \beta\log\sum_{y}\pi_\text{ref}(y\mid x)\exp\left(\frac{1}{\beta}r(x, y)\right)
\end{equation}

We define the projection $f$ as  
\begin{equation}
    f(r; \pi_\text{ref}, \beta)(x, y) = r(x, y) - \beta\log\sum_{y}\pi_\text{ref}(y\mid x)\exp\left(\frac{1}{\beta}r(x, y)\right)
\end{equation}

With some algebra this leads to the optimization objective:

\begin{equation}\label{eq:AC}
    \max_{\pi_{\theta}}\mathbb{E}_{\pi_{\theta}(y\mid x)}\bigg[\underbrace{r_{\phi}(x, y) -\beta\log\sum_{y}\pi_\text{ref}(y\mid x)\exp\left(\frac{1}{\beta}r_{\phi}(x, y)\right)}_{f(r_{\phi}, \pi_\text{ref}, \beta)} - \underbrace{\beta\log\frac{\pi_{\theta}(y\mid x)}{\pi_\text{ref}(y\mid x)}}_{\text{KL}}\bigg]
\end{equation}

The gradient of GSPO-token can be derived as:

\begin{align}
\nabla_{\theta} \mathcal{J}_\text{GSPO-token}(\theta)
=&\ 
\nabla_{\theta} \mathbb{E}_{ x \sim \mathcal{D},\, \{y_i\}_{i=1}^G \sim \pi_{\theta_\text{old}}( \cdot | x) }
\left[ 
\frac{1}{G} \sum_{i=1}^{G}
\frac{1}{|y_i|} \sum_{t=1}^{|y_i|} 
s_{i,t}(\theta) \widehat{A}_{i,t}
\right] \\
=&\ 
\mathbb{E}_{ x \sim \mathcal{D},\, \{y_i\}_{i=1}^G \sim \pi_{\theta_\text{old}}( \cdot | x) }
\left[ 
\frac{1}{G} \sum_{i=1}^{G} s_i (\theta) \cdot \frac{1}{|y_i|} \sum_{t=1}^{|y_i|} 
\widehat{A}_{i,t} \frac{ \nabla_{\theta} \pi_{\theta} (y_{i,t} | x, y_{i,<t}) }{ \pi_{\theta} (y_{i,t} | x, y_{i,<t}) }
\right] \\
=&\ 
\mathbb{E}_{ x \sim \mathcal{D},\, \{y_i\}_{i=1}^G \sim \pi_{\theta_\text{old}}( \cdot | x) }
\left[ 
\frac{1}{G} \sum_{i=1}^{G}  \left( \frac{ \pi_{\theta} (y_i | x) }{ \pi_{\theta_\text{old}} (y_i | x)} \right)^{\frac{1}{|y_i|}}
\cdot \frac{1}{|y_i|} \sum_{t=1}^{|y_i|}
\widehat{A}_{i,t} \nabla_{\theta} \log \pi_{\theta} (y_{i,t} | x, y_{i,<t})  
\right].
\label{equ:gspo-token_grad}
\end{align}

Let $\beta=\theta^{2/d}$, and $\lambda$ denote the actual rescale factor related to $s$, we   unify these positional interpolation methods as follows:

\begin{equation}	
	\fontsize{7.5}{7.5} \selectfont
	\label{eq:unified_rope}
	\begin{aligned}
		\left[cos\left(\frac{n}{\lambda(\beta)^0}\right), sin \left(\frac{n}{\lambda(\beta)^0}\right), cos\left(\frac{n}{\lambda(\beta)^1}\right), \cdot\cdot\cdot,  sin \left(\frac{n}{\lambda(\beta)^{d/2-1}}\right) \right]   
	\end{aligned}
\end{equation}

The optimization problem is then formulated as follows:

\begin{equation}
\begin{gathered}
		\label{eq:problem}

\underset {\mathbf{x}\in\mathbf{X}; \, |\mathbf{x}|\ge L'}{ \operatorname {arg\,min} } \,  \mathcal{L}\, \left( \text{LLM} (\text{RoPE}, \mathbf{X})\right),	\text{where \;} 
\\
\scalebox{0.93}{
$\underset {\begin{subarray}{l} i=0,\cdot\cdot,\frac{d}{2}-1;\\ n\in[ 0,|\mathbf{x}|);\end{subarray}}{\text{RoPE}_(n)}= {\left[\cdot\cdot,cos\left(\mathbb{I}(\hat{\lambda}_{i}, \hat{n})\times\frac{n}{\beta^i}\right),  sin\left(\mathbb{I}(\hat{\lambda}_{i}, \hat{n})\times\frac{n}{\beta^i}\right),\cdot\cdot\right] }$}\\
	\text{where \;} \mathbb{I}(\hat{\lambda}_{i},\hat{n})=\begin{cases}
	1&\mbox{\;  $n<\hat{n}$}\\
{\frac{1}{\lambda}_{i}}&\mbox{\; $n\geq\hat{n}$}
\end{cases}
	\end{gathered}
\end{equation}

OFT can be interpreted as minimizing the hyperspherical energy difference between the finetuned model and the pretrained model:

\begin{equation}\label{eq:oft_principle}
\footnotesize
\min_{\bm{W}} \left\| \text{HE}(\bm{W})-\text{HE}(\bm{W}^0)\right\|~~\Leftrightarrow~~\min_{\bm{W}} \bigg{\|} \sum_{i\neq j} \|\hat{\bm{w}}_i-\hat{\bm{w}}_j\|^{-1}-\sum_{i\neq j} \|\hat{\bm{w}}^0_i-\hat{\bm{w}}^0_j\|^{-1}\bigg{\|}
\end{equation}

where $\thickmuskip=2mu \medmuskip=2mu \hat{\bm{w}}_i:=\bm{w}_i/\|\bm{w}_i\|$ denotes the $i$-th normalized neuron, and the hyperspherical energy of a fully connected layer $\bm{W}$ is defined as $\thickmuskip=2mu \medmuskip=2mu \text{HE}(\bm{W}):= \sum_{i\neq j} \|\hat{\bm{w}}_i-\hat{\bm{w}}_j\|^{-1}$.

Formally, OFT seeks to optimize the orthogonal matrix $\thickmuskip=2mu \medmuskip=2mu \bm{R}\in\mathbb{R}^{d \times d}$ for a pretrained fully connected layer $\thickmuskip=2mu \medmuskip=2mu\bm{W}^0\in\mathbb{R}^{d\times n}$, changing the forward pass from $\thickmuskip=2mu \medmuskip=2mu\bm{z}=(\bm{W}^0)^\top\bm{x}$ to

\begin{equation}\label{eq:oft_general}
    \footnotesize
    \bm{z}=\bm{W}^\top\bm{x}=(\bm{R}\cdot\bm{W}^0)^\top\bm{x},~~~\text{s.t.}~\bm{R}^\top\bm{R}=\bm{R}\bm{R}^\top=\bm{I}
\end{equation}

where $\bm{W}$ denotes the OFT-finetuned weight matrix and $\bm{I}$ is an identity matrix.

Formally, OFT seeks to optimize the orthogonal matrix $\thickmuskip=2mu \medmuskip=2mu \bm{R}\in\mathbb{R}^{d \times d}$ for a pretrained fully connected layer $\thickmuskip=2mu \medmuskip=2mu\bm{W}^0\in\mathbb{R}^{d\times n}$, changing the forward pass from $\thickmuskip=2mu \medmuskip=2mu\bm{z}=(\bm{W}^0)^\top\bm{x}$ to

\begin{equation}\label{eq:oft_general}
    \footnotesize
    \bm{z}=\bm{W}^\top\bm{x}=(\bm{R}\cdot\bm{W}^0)^\top\bm{x},~~~\text{s.t.}~\bm{R}^\top\bm{R}=\bm{R}\bm{R}^\top=\bm{I}
\end{equation}

where $\bm{W}$ denotes the OFT-finetuned weight matrix and $\bm{I}$ is an identity matrix.

To address this, we propose to represent $\bm{R}$ with a block-diagonal matrix with $r$ blocks, leading to the following form:

\begin{equation}
    \footnotesize
    \bm{R}=\text{diag}(\bm{R}_1,\bm{R}_2,\cdots,\bm{R}_r)=\begin{bmatrix}
    \bm{R}_1\in \text{O}(\frac{d}{r}) &  &\\
    &\ddots & \\
    & & \bm{R}_r\in \text{O}(\frac{d}{r})
    \end{bmatrix}\in \text{O}(d)
\end{equation}

where $\text{O}(d)$ denotes the orthogonal group in dimension $d$, and $\thickmuskip=2mu \medmuskip=2mu \bm{R}\in\mathbb{R}^{d\times d}$ and $\thickmuskip=2mu \medmuskip=2mu \bm{R}_i\in\mathbb{R}^{d/r\times d/r},\forall i$ are orthogonal matrices.

Specifically, COFT uses the following forward pass:

\begin{equation}\label{eq:coft_general}
    \footnotesize
    \bm{z}=\bm{W}^\top\bm{x}=(\bm{R}\cdot\bm{W}^0)^\top\bm{x},~~~\text{s.t.}~\bm{R}^\top\bm{R}=\bm{R}\bm{R}^\top=\bm{I},~\norm{\bm{R}-\bm{I}}\leq \epsilon
\end{equation}

which has an orthogonality constraint and an $\epsilon$-deviation constraint to an identity matrix.

Specifically, COFT uses the following forward pass:

\begin{equation}\label{eq:coft_general}
    \footnotesize
    \bm{z}=\bm{W}^\top\bm{x}=(\bm{R}\cdot\bm{W}^0)^\top\bm{x},~~~\text{s.t.}~\bm{R}^\top\bm{R}=\bm{R}\bm{R}^\top=\bm{I},~\norm{\bm{R}-\bm{I}}\leq \epsilon
\end{equation}

which has an orthogonality constraint and an $\epsilon$-deviation constraint to an identity matrix.

Dequantization is the inverse:

\begin{equation}
    \text{dequant}(c^{\text{FP32}}, \mathbf{X}^{\text{Int8}}) = \frac{\mathbf{X}^{\text{Int8}}}{c^{\text{FP32}}} = \mathbf{X}^{\text{FP32}}
\end{equation}

Dequantization is the inverse:

\begin{equation}
    \text{dequant}(c^{\text{FP32}}, \mathbf{X}^{\text{Int8}}) = \frac{\mathbf{X}^{\text{Int8}}}{c^{\text{FP32}}} = \mathbf{X}^{\text{FP32}}
\end{equation}

Given a projection ${\mathbf{X} \mathbf{W} = \mathbf{Y}}$ with $\mathbf{X}\in  \mathbb{R}^{b\times h}$, $\mathbf{W}\in  \mathbb{R}^{h\times o}$ LoRA computes:

\begin{equation}
    \mathbf{Y} = \mathbf{X}\mathbf{W} + s\mathbf{X}\mathbf{L}_1\mathbf{L}_2,
\end{equation}

where $\mathbf{L}_1\in  \mathbb{R}^{h\times r}$ and $\mathbf{L}_2\in  \mathbb{R}^{r\times o}$, and $s$ is a scalar.

More formally, we estimate the $2^k$ values $q_i$ of the data type as follows:

\begin{equation}
q_i  = \frac{1}{2}\left( Q_X\left(\frac{i}{2^k+1}\right) + Q_X\left(\frac{i+1}{2^k+1}\right)\right),
\end{equation}

where $Q_X(\cdot)$ is the quantile function of the standard normal distribution $N(0,1)$.

To calculate the FLOPs of the forward pass, we use:

\begin{equation*}
  4 \cdot \text{seqlen}^2 \cdot \text{head dimension} \cdot \text{number of heads}.
\end{equation*}

Therefore, we stabilize gates with an additional state \mbox{$m_t$~\citep{Milakov:18arxiv}}:

\begin{align}
\label{eq:slstmstabil}
m_t \ &= \ \max \left( \log ( f_t ) + m_{t-1} , \log ( i_t ) \right) &\text{stabilizer state} \\
i'_t \ &= \ \!\exp \left( \log \left ( i_t \right) - m_t \right) \ = \ \!\exp \left( \tilde{i}_t - m_t \right) \ \, 
  &\text{stabil. input gate} \\
f'_t \ &= \ \!\exp \left( \log \left( f_t \right) + m_{t-1} - m_t \right) \ \, 
  &\text{stabil. forget gate}
\end{align}
